{
  "category": "Making turns",
  "entities": ["driver"],
  "evidence": "(1) A driver turning left at an intersection from a road (except a multi-lane road) must approach and enter the intersection from as near as practicable to the far left side of the road."
}

{
  "category": "Giving way",
  "entities": ["driver"], "evidence": "(1) A driver at an intersection with a stop sign or stop line, but without traffic lights, must stop and give way in accordance with this section."
}

{
  "category": "Speed limits",
  "entities": ["driver"],
  "evidence": "A driver must not drive at a speed over the speed limit applying to the driver for the length of road where the driver is driving."
}

{
  "category": "Making turns",
  "entities": ["driver"],
  "evidence": "(1) A driver changes direction if the driver changes direction to the left or the driver changes direction to the right."
}

{
  "category": "Traffic lights, traffic arrows and twin red lights",
  "entities": ["driver"],
  "evidence": "(1) A driver approaching or at traffic lights showing a red traffic light must stop-as near as practicable to, but before reaching, the stop line;"
}

{
  "category": "Giving way",
  "entities": [
    "driver"
  ],
  "evidence": "A driver at a level crossing with a stop sign must: (a) stop as near as practicable to, but before reaching, the stop line or, if there is no stop line, as near as practicable to, but before reaching, the stop sign;"
}

{
  "category": "Giving way",
  "entities": [
    "driver"
  ],
  "evidence": "If a driver stops at an intersection at a stop line, stop sign, or tra"
}

{
  "category": "Traffic signs and road markings",
  "entities": ["driver"],
  "evidence": "(1) A driver must not drive at night, or in hazardous weather conditions causing reduced visibility, unless..."
}

{
  "category": "Making turns",
  "entities": [
    "pedestrian"
  ],
  "evidence": "A pedestrian must not be on a length of road to which a road access sign applies if information on or with the sign indicates that pedestrians are not permitted beyond the sign."
}

{
  "category": "Traffic signs and road markings",
  "entities": ["driver"],
  "evidence": "If there is a left turn only sign at an intersection, a driver must turn left at the intersection."
}

{
  "category": "other",
  "entities": [
    "driver"
  ],
  "evidence": "A single-seat bicycle with a child's seat attached is designed to carry 2 people, 1 on the bicycle seat and 1 on the attached child's seat."
}

{
  "category": "Making turns",
  "entities": [
    "driver"
  ],
  "evidence": "(1) A driver involved in a crash must comply with this section."
}

{
  "category": "Making turns",
  "entities": ["driver"],
  "evidence": "The driver of a tram approaching or at T lights showing a red T light must stop"
}

{
  "category": "Making turns",
  "entities": [
    "driver"
  ],
  "evidence": "(2) Subsection (1) (c) does not apply if the driver is- (a) reversing the vehicle; or (b) exe"
}

{
  "category": "Giving way",
  "entities": ["driver"],
  "evidence": "An exemption provision does not apply to the driver of a police vehicle if... the driver is taking reasonable care; and it is reasonable that the provision should not apply having regard to the road and traffic conditions at the time;"
}

